"""Enforce dependency direction before pipeline components are introduced."""

import ast
import sys
from collections.abc import Iterable
from pathlib import PurePosixPath

from verification.findings import Finding
from verification.policy import Policy

PACKAGE_LAYER_PARTS = 2
SOURCE_MODULE_PARTS = 3


def imported_modules(tree: ast.AST, module: str) -> Iterable[tuple[str, int]]:
    """Resolve explicit absolute and relative imports to dotted module names."""
    for node in ast.walk(tree):
        yield from imports_at_node(node, module)


def imports_at_node(node: ast.AST, module: str) -> Iterable[tuple[str, int]]:
    """Resolve one import statement without hiding relative layer dependencies."""
    if isinstance(node, ast.Import):
        yield from ((alias.name, node.lineno) for alias in node.names)
    if isinstance(node, ast.ImportFrom):
        prefix = node.module or ""
        if node.level:
            prefix = ".".join([*module.split(".")[: -node.level], prefix]).strip(".")
        yield from ((f"{prefix}.{alias.name}", node.lineno) for alias in node.names)


def violation(target: str, layer: str, policy: Policy) -> str | None:
    """Classify the requested dependency against the canonical layer contract."""
    parts = target.split(".")
    if parts[0] == policy.package:
        if len(parts) < PACKAGE_LAYER_PARTS or parts[1] not in policy.layers[layer]:
            return f"{layer} cannot import {target}; use an allowed layer or a port."
    elif layer in {"domain", "ports", "application"} and parts[0] not in sys.stdlib_module_names:
        return f"{layer} cannot import external dependency {target}; introduce a port."
    return None


def check_architecture(path: str, source: str, policy: Policy) -> Iterable[Finding]:
    """Validate package placement and import direction for production Python."""
    parts = PurePosixPath(path).with_suffix("").parts
    if parts[0] != "src":
        return
    if len(parts) < SOURCE_MODULE_PARTS or parts[:2] != ("src", policy.package):
        yield Finding(path, 1, "ARCH001", "Place production modules inside the canonical package.")
        return
    layer = "domain" if parts[-1] == "__init__" and len(parts) == SOURCE_MODULE_PARTS else parts[2]
    if layer not in policy.layers:
        yield Finding(path, 1, "ARCH001", "Place production modules inside a declared layer.")
        return
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return  # Syntax is reported by the Python parser check.
    module = ".".join(parts[1:])
    for target, line in imported_modules(tree, module):
        message = violation(target, layer, policy)
        if message:
            yield Finding(path, line, "ARCH002", message)

"""AST design checks beyond standard Ruff and mypy rules."""

import ast
import re
from collections.abc import Iterable

from verification.findings import Finding
from verification.policy import Policy

LOOPS = (ast.For, ast.AsyncFor, ast.While)
COMPREHENSIONS = (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)
DEFINITIONS = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)


class DesignVisitor(ast.NodeVisitor):
    """Reject excessive iteration nesting and generic declaration names."""

    def __init__(self, path: str, policy: Policy) -> None:
        self.path = path
        self.policy = policy
        self.depth = 0
        self.findings: list[Finding] = []

    def visit(self, node: ast.AST) -> None:
        """Keep loop depth lexical, including comprehension generators."""
        if isinstance(node, DEFINITIONS):
            self.check_name(node)
        self.check_binding(node)
        previous_depth = self.depth
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
            self.depth = 0
        increment = self.loop_increment(node)
        self.depth += increment
        if isinstance(node, (*LOOPS, *COMPREHENSIONS)) and self.depth > self.policy.max_loop_depth:
            self.findings.append(
                Finding(
                    self.path, node.lineno, "PY001", "Extract nested iteration into a named step."
                )
            )
        self.generic_visit(node)
        self.depth = previous_depth

    def check_binding(self, node: ast.AST) -> None:
        """Require owned variables and parameters to name their content."""
        if (
            isinstance(node, (ast.Name, ast.arg))
            and binding_name(node) in self.policy.forbidden_names
        ):
            self.findings.append(
                Finding(self.path, node.lineno, "PY002", "Name the specific domain responsibility.")
            )

    def loop_increment(self, node: ast.AST) -> int:
        """Count iteration constructs, including multiple comprehension clauses."""
        if isinstance(node, LOOPS):
            return 1
        if isinstance(node, COMPREHENSIONS):
            return len(node.generators)
        return 0

    def check_name(self, node: ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef) -> None:
        """Require declarations to identify a responsibility rather than a generic bucket."""
        words = re.sub(r"([a-z])([A-Z])", r"\1_\2", node.name).lower().strip("_").split("_")
        if words[-1] in self.policy.forbidden_names:
            self.findings.append(
                Finding(self.path, node.lineno, "PY002", "Name the specific domain responsibility.")
            )


def check_python(path: str, source: str, policy: Policy) -> Iterable[Finding]:
    """Parse real syntax and return deterministic design findings."""
    try:
        tree = ast.parse(source, filename=path)
    except SyntaxError as error:
        yield Finding(path, error.lineno or 1, "PY000", str(error.msg))
        return
    visitor = DesignVisitor(path, policy)
    visitor.visit(tree)
    yield from visitor.findings


def binding_name(node: ast.AST) -> str:
    """Identify names owned by this module, excluding imported API attributes."""
    if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
        return node.id
    if isinstance(node, ast.arg):
        return node.arg
    return ""
